#!/bin/bash
set -e

apt-get update
apt-get install -y curl jq file tar unzip zip ca-certificates

mkdir -p /mnt/server
cd /mnt/server

# Limpiar binarios anteriores para reinstalaciones limpias, preservando mundos y configs
rm -rf bin PocketMine-MP.phar

ARCH=$([[ "$(uname -m)" == "x86_64" ]] && printf "amd64" || printf "arm64")
VERSION="${VERSION:-PM5}"
VERSION="${VERSION^^}"

if [[ "${VERSION}" == "PM4" ]]; then
  REQUIRED_PHP_VERSION="8.1"
  PHP_VARIANT="PM4"
  PHP_URL="https://github.com/QXRND/PHP-Binaries/releases/download/php-8.1-latest/php81pm4.tar.gz"
  DOWNLOAD_REPO="QXRND/PocketMine-MP-PM4"
  DOWNLOAD_ASSET="PocketMine-MP.phar"
  FALLBACK_PHAR="https://github.com/QXRND/PocketMine-MP-PM4/releases/download/v4.26.0-qxrnd.3/PocketMine-MP.phar"
elif [[ "${VERSION}" == "PM5" ]]; then
  REQUIRED_PHP_VERSION="8.2"
  PHP_VARIANT="PM5"
  PHP_URL="https://github.com/QXRND/PHP-Binaries/releases/download/php-8.2-latest/php82pm5.tar.gz"
  DOWNLOAD_REPO="QXRND/PocketMine-MP-PM5"
  DOWNLOAD_ASSET="PocketMine-MP.phar"
  FALLBACK_PHAR="https://github.com/QXRND/PocketMine-MP-PM5/releases/download/v5.44.5-qxrnd.19/PocketMine-MP.phar"
elif [[ "${VERSION}" == "PM6" ]]; then
  REQUIRED_PHP_VERSION="8.3"
  PHP_VARIANT="PM6"
  PHP_URL="https://github.com/pmmp/PHP-Binaries/releases/download/pm5-php-8.3-latest/PHP-8.3-Linux-x86_64-PM5.tar.gz"
  DOWNLOAD_REPO="QXRND/PocketMine-MP-PM6"
  DOWNLOAD_ASSET="PocketMine-MP.phar"
  FALLBACK_PHAR="https://github.com/QXRND/PocketMine-MP-PM6/releases/download/qxrnd-26.44/PocketMine-MP.phar"
else
  echo "Unsupported version: ${VERSION}. Use PM4, PM5 or PM6."
  exit 1
fi

if [[ "${ARCH}" != "amd64" ]]; then
  echo "This egg currently supports x86_64/amd64 PHP binaries only."
  exit 1
fi

echo "=========================================================="
echo " Instalando PocketMine-MP ${VERSION} (QXRND)               "
echo " Mantenedor: DevPapo | Licencias: licences.scon.host      "
echo "=========================================================="

# 1. Descarga del runtime de PHP
echo "Descargando entorno PHP ${REQUIRED_PHP_VERSION} para ${VERSION}..."
PHP_OK=false
if curl -sSL --fail --location --retry 3 --connect-timeout 10 "${PHP_URL}" | tar -xzv; then
  PHP_OK=true
else
  echo "Fallo descarga de PHP_URL principal, intentando mirror oficial de PMMP..."
  FALLBACK_PHP="https://github.com/pmmp/PHP-Binaries/releases/download/pm5-php-${REQUIRED_PHP_VERSION}-latest/PHP-${REQUIRED_PHP_VERSION}-Linux-x86_64-PM5.tar.gz"
  if curl -sSL --fail --location --retry 3 --connect-timeout 10 "${FALLBACK_PHP}" | tar -xzv; then
    PHP_OK=true
  fi
fi

if [ "$PHP_OK" = "false" ] || [ ! -f "bin/php7/bin/php" ]; then
  echo "Error fatal: No se pudo instalar el binario de PHP."
  exit 1
fi

chmod -R +x bin/

# Ajuste de php.ini para evitar errores de opcache o extension_dir
if [[ -f bin/php7/bin/php.ini ]]; then
  sed -i -E 's|^[[:space:]]*zend_extension[[:space:]]*=.*opcache\.so.*$|; zend_extension=opcache.so|' bin/php7/bin/php.ini
  EXT_DIR=$(find /mnt/server/bin/ -type d -name '*debug-zts*' 2>/dev/null | head -n 1)
  if [ -n "$EXT_DIR" ]; then
    grep -q '^extension_dir' bin/php7/bin/php.ini && \
      sed -i "s{^extension_dir=.*{extension_dir=\"$EXT_DIR\"{" bin/php7/bin/php.ini || \
      echo "extension_dir=\"$EXT_DIR\"" >> bin/php7/bin/php.ini
  fi
fi

# 2. Descargar PocketMine-MP.phar desde Release
echo "Descargando PocketMine-MP.phar (${VERSION})...
"
PHAR_OK=false

DOWNLOAD_LINK=$(curl -sSL --connect-timeout 5 "https://api.github.com/repos/${DOWNLOAD_REPO}/releases/latest" 2>/dev/null | jq -r --arg asset "${DOWNLOAD_ASSET}" '.assets[]? | select(.name == $asset) | .browser_download_url' 2>/dev/null | head -n 1)

if [[ -n "${DOWNLOAD_LINK}" && "${DOWNLOAD_LINK}" != "null" ]]; then
  echo "Descargando desde latest release: ${DOWNLOAD_LINK}"
  if curl --fail --location --retry 3 --connect-timeout 15 "${DOWNLOAD_LINK}" --output PocketMine-MP.phar; then
    if [[ -s PocketMine-MP.phar && $(wc -c < PocketMine-MP.phar) -gt 1000000 ]]; then
      PHAR_OK=true
    fi
  fi
fi

if [[ "$PHAR_OK" = "false" ]]; then
  echo "Aviso: Usando fallback directo de release: ${FALLBACK_PHAR}"
  curl --fail --location --retry 3 --connect-timeout 15 "${FALLBACK_PHAR}" --output PocketMine-MP.phar || true
  if [[ -s PocketMine-MP.phar && $(wc -c < PocketMine-MP.phar) -gt 1000000 ]]; then
    PHAR_OK=true
  fi
fi

if [[ "$PHAR_OK" = "false" ]]; then
  echo "Error fatal: No se pudo descargar PocketMine-MP.phar."
  exit 1
fi

chmod +x PocketMine-MP.phar

# 3. Provisionar plugin SCON Licensing Guard en PM5
if [[ "${VERSION}" == "PM5" ]]; then
  echo "Configurando plugin SCON Licensing Guard (PMMP-QXRND)..."
  mkdir -p plugins/PMMP-QXRND/src/devpapo/pmmpqxrnd
  mkdir -p plugins/PMMP-QXRND/resources
  mkdir -p plugin_data/PMMP-QXRND

  cat << 'EOF_PLUGIN_YML' > plugins/PMMP-QXRND/plugin.yml
name: PMMP-QXRND
version: 1.0.0
main: devpapo\pmmpqxrnd\Main
api: 5.0.0
author: devpapo
description: SCON Licensing Security Guard (Militar Ed25519) para PMMP-QXRND
website: https://licences.scon.host
load: STARTUP
EOF_PLUGIN_YML

  cat << 'EOF_CONFIG_YML' > plugins/PMMP-QXRND/resources/config.yml
license-key: "SCON-XXXX-XXXX-XXXX-XXXX"
EOF_CONFIG_YML

  if [ ! -f "plugin_data/PMMP-QXRND/config.yml" ]; then
    echo "license-key: \"${LICENSE_KEY:-SCON-XXXX-XXXX-XXXX-XXXX}\"" > plugin_data/PMMP-QXRND/config.yml
  fi

  cat << 'EOF_MAIN_PHP' > plugins/PMMP-QXRND/src/devpapo/pmmpqxrnd/Main.php
<?php
declare(strict_types=1);

namespace devpapo\pmmpqxrnd;

use pocketmine\plugin\PluginBase;

class Main extends PluginBase {

    protected function onEnable(): void {
        $this->saveDefaultConfig();
        $key = (string) $this->getConfig()->get("license-key", "");
        if (($key === "" || str_contains($key, "XXXX")) && getenv("LICENSE_KEY") !== false && getenv("LICENSE_KEY") !== "") {
            $key = trim((string) getenv("LICENSE_KEY"));
        }
        if (!(new SconLicenseGuard($this))->start($key)) {
            $this->getServer()->shutdown();
            return;
        }
        $this->getLogger()->info("§a[SCON] PMMP-QXRND inicializado y protegido correctamente.");
    }
}
EOF_MAIN_PHP

  cat << 'EOF_GUARD_PHP' > plugins/PMMP-QXRND/src/devpapo/pmmpqxrnd/SconLicenseGuard.php
<?php
declare(strict_types=1);

namespace devpapo\pmmpqxrnd;

use pocketmine\plugin\PluginBase;
use pocketmine\scheduler\ClosureTask;
use OpenSSLAsymmetricKey;

final class SconLicenseGuard {

    private const VERIFY_URL = "https://licences.scon.host/api/v1/license/verify";
    private const PROJECT_SLUG = "pmmp-qxrnd";
    private const TIER = "military_ed25519";
    private const ECDSA_P384_PUBLIC_KEY = "MHYwEAYHKoZIzj0CAQYFK4EEACIDYgAE9BMnUwTaB0pnte0tjMRg7AVHI1hscsxZhNku/hfSh5XDy9M3Yqpj+yzrv/PSKJpHnYkHUj5lSSRCDfBCN1BnZ5ggskOOQmhgqtaCADEDKhLoI9kiQXLayzcXpF5ZBO9X";
    private const ED25519_PUBLIC_KEY = "MCowBQYDK2VwAyEAkP2A+MJNYZeZacF2wn7FlYBbPPPAqajQHgyXKtbVOk0=";
    private const MAX_CLOCK_DRIFT_SECONDS = 120;
    private const RECHECK_MINUTES = 30;

    public function __construct(private PluginBase $plugin) {}

    public function start(string $key): bool {
        $result = $this->verifyLicense($key);
        if (!$result["valid"]) {
            $this->shutdown("Licencia rechazada ({$result["status"]}): {$result["message"]}");
            return false;
        }
        $this->plugin->getLogger()->info("[SCON] Licencia verificada.");
        $this->plugin->getScheduler()->scheduleRepeatingTask(new ClosureTask(function () use ($key): void {
            $r = $this->verifyLicense($key);
            if (!$r["valid"] && $r["status"] !== "NETWORK_ERROR") {
                $this->shutdown("Licencia rechazada ({$r["status"]}): {$r["message"]}");
            }
        }), 20 * 60 * self::RECHECK_MINUTES);
        return true;
    }

    private function shutdown(string $reason): void {
        $this->plugin->getLogger()->error("[SCON] " . $reason);
        $this->plugin->getServer()->getPluginManager()->disablePlugin($this->plugin);
    }

    public function verifyLicense(string $key): array {
        $key = trim($key);
        if ($key === "" || str_contains($key, "XXXX")) {
            return ["valid" => false, "status" => "NO_KEY", "message" => "Configura license-key en config.yml"];
        }
        if (!function_exists("sodium_crypto_sign_verify_detached")) {
            return ["valid" => false, "status" => "INVALID", "message" => "Este grado requiere la extension sodium de PHP"];
        }
        $nonce = bin2hex(random_bytes(24));
        $eph = self::newP384Key();
        if ($eph === null) {
            return ["valid" => false, "status" => "INVALID", "message" => "OpenSSL no soporta la curva P-384"];
        }
        $epk = self::spki($eph);
        $build = $this->buildFile();
        $description = $this->plugin->getDescription();
        $body = [
            "protocol" => 2,
            "license_key" => $key,
            "project_slug" => self::PROJECT_SLUG,
            "product_name" => $description->getName(),
            "plugin_version" => $description->getVersion(),
            "server_port" => $this->plugin->getServer()->getPort(),
            "client_nonce" => $nonce,
            "client_timestamp" => time(),
            "client_epk" => $epk,
            "hwid" => $this->computeHwid(),
            "binary_hash" => $build !== "" ? (string) hash_file("sha512", $build) : ""
        ];
        $body["binary_hash_sha3"] = $build !== "" ? (string) hash_file("sha3-512", $build) : "";
        $device = $this->deviceKey();
        $body["device_pub"] = self::spki($device);
        $message = implode("\n", ["SCON-DEV-1", self::PROJECT_SLUG, $key, $nonce, (string) $body["client_timestamp"],
            $body["hwid"], $body["binary_hash"], $body["binary_hash_sha3"], $epk]);
        $signature = "";
        openssl_sign($message, $signature, $device, OPENSSL_ALGO_SHA384);
        $body["device_sig"] = base64_encode($signature);

        $ch = curl_init(self::VERIFY_URL);
        curl_setopt_array($ch, [
            CURLOPT_RETURNTRANSFER => true,
            CURLOPT_POST => true,
            CURLOPT_POSTFIELDS => json_encode($body),
            CURLOPT_HTTPHEADER => ["Content-Type: application/json", "User-Agent: SCON-PHP/3"],
            CURLOPT_CONNECTTIMEOUT => 10,
            CURLOPT_TIMEOUT => 15
        ]);
        $raw = curl_exec($ch);
        $res = is_string($raw) ? json_decode($raw, true) : null;
        if (!is_array($res)) {
            return ["valid" => false, "status" => "NETWORK_ERROR", "message" => "No se pudo contactar con el servidor de licencias"];
        }
        if (!isset($res["payload"]) || !is_string($res["payload"]) || !self::verifySignatures($res)) {
            return ["valid" => false, "status" => "INVALID_SIGNATURE", "message" => "Firma del servidor invalida o ausente"];
        }
        $outer = json_decode($res["payload"], true);
        $encrypted = is_array($outer) && isset($outer["epk"]);
        $plain = $encrypted ? self::openEnvelope($outer, $nonce, $eph) : $res["payload"];
        $data = is_string($plain) ? json_decode($plain, true) : null;
        if (!is_array($data) || ($data["nonce"] ?? "") !== $nonce || ($data["project"] ?? "") !== self::PROJECT_SLUG) {
            return ["valid" => false, "status" => "REPLAY", "message" => "La respuesta no corresponde a esta peticion"];
        }
        if (abs(time() - (int) ($data["issued_at"] ?? 0)) > self::MAX_CLOCK_DRIFT_SECONDS) {
            return ["valid" => false, "status" => "CLOCK_DRIFT", "message" => "Desfase de reloj excesivo"];
        }
        if (!$encrypted && ($data["valid"] ?? false) === true) {
            return ["valid" => false, "status" => "UNENCRYPTED", "message" => "Respuesta sin cifrar: se rechaza"];
        }
        $valid = $encrypted && ($data["valid"] ?? false) === true;
        return ["valid" => $valid, "status" => (string) ($data["status"] ?? "INVALID"), "message" => (string) ($data["message"] ?? "")];
    }

    private static function verifySignatures(array $res): bool {
        $payload = $res["payload"];
        $sig = base64_decode((string) ($res["sig"] ?? ""), true);
        if ($sig === false || $sig === "" || openssl_verify($payload, $sig, self::pem(self::ECDSA_P384_PUBLIC_KEY), OPENSSL_ALGO_SHA384) !== 1) {
            return false;
        }
        $sig2 = base64_decode((string) ($res["sig2"] ?? ""), true);
        $edKey = substr((string) base64_decode(self::ED25519_PUBLIC_KEY), -32);
        if ($sig2 === false || strlen($sig2) !== 64 || !sodium_crypto_sign_verify_detached($sig2, $payload, $edKey)) {
            return false;
        }
        return true;
    }

    private static function openEnvelope(array $env, string $nonce, \OpenSSLAsymmetricKey $clientKey): ?string {
        $serverKey = openssl_pkey_get_public(self::pem((string) ($env["epk"] ?? "")));
        if ($serverKey === false) return null;
        $shared = openssl_pkey_derive($serverKey, $clientKey);
        if ($shared === false) return null;
        $keys = hash_hkdf("sha384", $shared, 32, "SCON-ENV-1|" . self::TIER . "|" . self::PROJECT_SLUG, $nonce);
        $ct = (string) base64_decode((string) ($env["ct"] ?? ""));
        if (strlen($ct) < 16) return null;
        $data = openssl_decrypt(substr($ct, 0, -16), "aes-256-gcm", substr($keys, 0, 32), OPENSSL_RAW_DATA,
            (string) base64_decode((string) ($env["iv"] ?? "")), substr($ct, -16), $nonce);
        if ($data === false) return null;
        return $data;
    }

    private static function newP384Key(): ?\OpenSSLAsymmetricKey {
        $key = openssl_pkey_new(["private_key_type" => OPENSSL_KEYTYPE_EC, "curve_name" => "secp384r1"]);
        return $key === false ? null : $key;
    }

    private static function spki(\OpenSSLAsymmetricKey $key): string {
        $pem = (string) (openssl_pkey_get_details($key)["key"] ?? "");
        return (string) preg_replace('/-----[^-]+-----|\s+/', '', $pem);
    }

    private static function pem(string $spkiB64): string {
        return "-----BEGIN PUBLIC KEY-----\n" . chunk_split($spkiB64, 64, "\n") . "-----END PUBLIC KEY-----\n";
    }

    private function deviceKey(): \OpenSSLAsymmetricKey {
        $file = $this->plugin->getDataFolder() . "scon-device.key";
        if (is_file($file)) {
            $key = openssl_pkey_get_private((string) file_get_contents($file));
            if ($key !== false) return $key;
        }
        $key = self::newP384Key();
        $pem = "";
        openssl_pkey_export($key, $pem);
        @mkdir($this->plugin->getDataFolder(), 0700, true);
        file_put_contents($file, $pem);
        @chmod($file, 0600);
        return $key;
    }

    private function computeHwid(): string {
        $id = "";
        foreach (["/etc/machine-id", "/var/lib/dbus/machine-id"] as $file) {
            $id = is_readable($file) ? trim((string) file_get_contents($file)) : "";
            if ($id !== "") break;
        }
        if ($id === "" && PHP_OS_FAMILY === "Windows") {
            $id = (string) getenv("COMPUTERNAME") . (string) getenv("PROCESSOR_IDENTIFIER");
        }
        if ($id === "") {
            $file = $this->plugin->getDataFolder() . "scon-hwid.id";
            $id = is_readable($file) ? trim((string) file_get_contents($file)) : "";
            if ($id === "") {
                $id = bin2hex(random_bytes(32));
                @mkdir($this->plugin->getDataFolder(), 0700, true);
                if (@file_put_contents($file, $id) !== false) @chmod($file, 0600);
            }
        }
        return hash("sha256", "scon-hwid-2|" . $id);
    }

    private function buildFile(): string {
        $file = $this->plugin->getFile();
        if (str_starts_with($file, "phar://")) $file = rtrim(substr($file, 7), "/");
        return is_file($file) ? $file : "";
    }
}
EOF_GUARD_PHP
fi

# 4. Crear server.properties si no existe
if [[ ! -f server.properties ]]; then
  cat << 'EOF_PROPERTIES' > server.properties
motd=PocketMine-MP Bedrock Server
server-port=19132
server-ip=0.0.0.0
view-distance=16
white-list=off
max-players=20
gamemode=0
difficulty=1
pvp=on
enable-query=on
enable-rcon=off
auto-save=on
EOF_PROPERTIES
fi

touch banned-ips.txt banned-players.txt ops.txt white-list.txt server.log
mkdir -p players worlds plugins resource_packs
echo "${VERSION} instalacion completada exitosamente! Mantenedor: admin@scon.host"
